style.css:
@-moz-document domain("roblox.com") {
/* Fixes new Roblox homepage (June 2024) */
    #home-page, 
    .app-body,
    .main-content {
        background-image: url('https://cdn.discordapp.com/attachments/1051432403392020481/1378620143210598410/Sunset_at_the_Lake_1.gif') !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
    }

    /* Dark overlay for text readability */
    .games-container,
    .rbx-home-page,
    .container-main {
        background-color: rgba(0, 0, 0, 0.65) !important;
        backdrop-filter: blur(6px) !important;
    }
    
    /* Fix for white flash before loading */
    body {
        background-color: #000 !important;
    }
}
